#!/bin/env bash

# https://codeberg.org/librewolf/issues/issues/2847

# Merges packaged policies + local overlay; overlay wins on conflicts.
# Regenerated by the pacman hook so it keeps tracking upstream defaults.
set -euo pipefail
SRC="${SRC:-/usr/lib/librewolf/distribution/policies.json}"
DST="${DST:-/etc/librewolf/policies/policies.json}"
OVERLAY="${OVERLAY:-/etc/librewolf/policies/overlay.json}"
if [[ "$DST" == "-" ]]; then
	jq -s '.[0].policies *= .[1] | .[0]' "$SRC" "$OVERLAY"
else
	mkdir -p "$(dirname "$DST")"
	jq -s '.[0].policies *= .[1] | .[0]' "$SRC" "$OVERLAY" >"$DST.tmp" &&
		mv "$DST.tmp" "$DST"
fi
